#include <bits/stdc++.h>
using namespace std;
using ll = long long;

int main() {
	ll n, k;
	cin >> n >> k;
	map<ll, ll> mp;
	for (int i = 0; i < n; i++) {
		ll a;
		cin >> a;
		mp[a]++;
	}
	vector<ll> v;
	for (auto [x, c_x] : mp) v.push_back(x * c_x);
	sort(v.begin(), v.end());
	for (int i = 0; i < k; i++) if (!v.empty()) v.pop_back();
	ll ans = reduce(v.begin(), v.end());
	cout << ans << '\n';
}
